 "content": "from collections import Counter, deque


def _components(grid):
    h, w = len(grid), len(grid[0])
    seen, result = set(), []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    a, b = x + dx, y + dy
                    if 0 <= a < h and 0 <= b < w and (a, b) not in seen and grid[a][b] == color:
                        seen.add((a, b))
                        q.append((a, b))
            result.append((color, cells))
    return result


def _corner(cells):
    rs = [r for r, c in cells]
    cs = [c for r, c in cells]
    r0, r1, c0, c1 = min(rs), max(rs), min(cs), max(cs)
    pts = set(cells)
    forms = {
        "tl": {(r0, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)},
        "tr": {(r0, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)},
        "bl": {(r1, c) for c in range(c0, c1 + 1)} | {(r, c0) for r in range(r0, r1 + 1)},
        "br": {(r1, c) for c in range(c0, c1 + 1)} | {(r, c1) for r in range(r0, r1 + 1)},
    }
    if r0 < r1 and c0 < c1:
        for orient, shape in forms.items():
            if pts == shape:
                return orient, (r0, r1, c0, c1)
    return None


def transform(grid):
    if not grid or not grid[0]:
        return [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid)
    cell_to_comp = {}
    for i, (color, cells) in enumerate(comps):
        for cell in cells:
            cell_to_comp[cell] = i
    markers = []
    for i, (color, cells) in enumerate(comps):
        shape = _corner(cells) if color != bg else None
        if shape:
            markers.append((i, color, shape[0], shape[1]))

    out = [row[:] for row in grid]
    # Each L-shaped marker casts its two arms outward from the elbow;
    # the first object encountered on an outward ray takes the marker's color.
    for marker_i, color, orient, (r0, r1, c0, c1) in markers:
        if orient == "tl":
            rays = ((r0 - 1, c0, -1, 0), (r0, c0 - 1, 0, -1))
        elif orient == "tr":
            rays = ((r0 - 1, c1, -1, 0), (r0, c1 + 1, 0, 1))
        elif orient == "bl":
            rays = ((r1 + 1, c0, 1, 0), (r1, c0 - 1, 0, -1))
        else:  # br
            rays = ((r1 + 1, c1, 1, 0), (r1, c1 + 1, 0, 1))
        for r, c, dr, dc in rays:
            while 0 <= r < h and 0 <= c < w:
                if grid[r][c] != bg:
                    target_i = cell_to_comp[(r, c)]
                    if target_i != marker_i:
                        for rr, cc in comps[target_i][1]:
                            out[rr][cc] = color
                    break
                r += dr
                c += dc
    return out


